import { registerWebComponents } from '@domg-wc/common';
import { VlCheckboxComponent } from '@domg-wc/components/form';

registerWebComponents([VlCheckboxComponent]);

// vl-input volgt enkel op een klik van de gebruiker, vl-change ook op een wijziging van checked door code.
// event.detail.checked is de nieuwe toestand; event.detail.value staat er enkel in als de checkbox aangevinkt is
// (de value, of 'on' zonder value).
document.querySelector('#checkbox-default').addEventListener('vl-change', (event) => {
    console.log(event.detail.checked, event.detail.value);
});
